icon":"/investments/pod-stokiem-apartamenty/icons/icon-smart-home.svg","text":"Instalacja inteligentnego domu "},{"icon":"/investments/pod-stokiem-apartamenty/icons/icon-cooler.svg","text":"Instalacja pod Klimatyzację"},{"icon":"/investments/pod-stokiem-apartamenty/icons/icon-heat-pump.svg","text":"Pompa Ciepła"},{"icon":"/investments/pod-stokiem-apartamenty/icons/icon-heat-recovery.svg","text":"Rekuperacja"}],"editable":true,"label":"Cechy techniczne"},"overlayHeader":{"value":"Prywatność, przestrzeń i nowoczesna architektura - Wola Justowska","editable":true,"label":"Nagłówek na zdjęciu"},"overlaySubHeader":{"value":"Tylko cztery, jednopoziomowe lokale w zabudowie bliźniaczej. Dwa apartamenty z ogrodami i dwa z tarasami na dachu - w jednej z najbardziej cenionych części Krakowa.","editable":true,"label":"Podtytuł na zdjęciu"},"header":{"value":"O inwestycji","editable":true,"label":"Nagłówek"},"subHeader":{"value":"Pod Stokiem Apartamenty to dwa budynki w zabudowie bliźniaczej przy ul. Pod Stokiem w Woli Justowskiej. Powstają tylko cztery lokale, każdy jednopoziomowy, z dużymi przeszkleniami i dopracowanymi proporcjami wnętrz. Architektura łączy jasne bryły z detalem drewna i kamienia. To propozycja dla osób, które szukają spokoju, prywatności i jakości w jednej z najlepiej ocenianych części Krakowa.","editable":true,"label":"Opis"},"interiorsHeader":{"value":"Wnętrza o dużym potencjale","editable":true,"label":"Nagłówek wnętrz"},"interiorsSubHeader":{"value":"To przestrzeń, którą możesz zaaranżować zgodnie z własnymi potrzebami - od minimalistycznej elegancji po ciepły, rodzinny klimat. Przemyślany układ funkcjonalny oraz duże przeszklenia sprawiają, że wnętrza są jasne, ustawne i pełne naturalnego światła.","editable":true,"label":"Podtytuł wnętrz"}}},{"id":"inwest-map","component":"InwestMap","type":"section","label":"InwestMap (sekcja jeszcze bez komponentu — patrz src/components/investments/pod-stokiem-apartamenty/template.tsx)","fields":{"header":{"value":"Funkcjonalność i spokój","editable":true,"label":"Nagłówek"},"subHeader":{"value":"Pod Stokiem Apartamenty to inwestycja stworzona z myślą o osobach, które chcą mieszkać wygodnie i spokojnie. Jednopoziomowy układ każdego lokalu zapewnia komfort codziennego użytkowania.Apartamenty na parterze oferują bezpośrednie wyjście do ogrodów, natomiast lokale na piętrze dysponują dodatkowymi tarasami na dachu. W standardzie przewidziano rozwiązania, które realnie podnoszą jakość  życia, takie jak pompa ciepła i rekuperacja. Dodatkowo zaplanowano przygotowanie instalacji pod ładowarkę samochodu elektrycznego. Całość odpowiada na potrzeby osób, ceniących wysoki standard, funkcjonalność i spokojne otoczenie","editable":true,"label":"Opis"}}},{"id":"apartaments","component":"Apartaments","type":"section","label":"Oferta mieszkań","fields":{"offerHeader":{"value":"Oferta Mieszkań","editable":true,"label":"Nagłówek oferty"},"downloadsHeader":{"value":"Pliki do pobrania","editable":true,"label":"Nagłówek plików"},"apartments":{"value":[{"unit":"M1A","rooms":"4","area":"124.31","gardenArea":"300","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"Miejsca Parkingowe M1A","rooms":"-","area":"25.00","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"M1B","rooms":"5","area":"139.96","gardenArea":"162.87","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"Miejsca Parkingowe M1B","rooms":"-","area":"25.00","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"M2A","rooms":"4","area":"124.31","gardenArea":"335","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"Miejsca Parkingowe M2A","rooms":"-","area":"25.00","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"M2B","rooms":"5","area":"139.96","gardenArea":"162.87","pricePerM2":"17 700","price":"2 477 292","status":"Wolny","images":[]},{"unit":"Miejsca Parkingowe M2B","rooms":"-","area":"25.00","pricePerM2":"-","price":"100 000","status":"Wolny","images":[]}],"editable":true,"label":"Lista mieszkań i miejsc postojowych (zdjęcia per-lokal do uzupełnienia w panelu admina)"},"prospectusHeader":{"value":"Prospekt informacyjny","editable":true,"label":"Nagłówek prospektu"},"prospectusText":{"value":"Kompletne informacje o inwestycji dotyczące standardu, harmonogramu realizacji oraz aspektów prawnych pozwalają poznać Pod Stokiem Apartamenty w pełnym kontekście i podjąć świadomą decyzję.","editable":true,"label":"Opis prospektu"},"prospectusFile":{"value":null,"editable":true,"label":"Plik prospektu (PDF, do uzupełnienia)"},"standardHeader":{"value":"Standard wykończenia","editable":true,"label":"Nagłówek standardu"},"standardText":{"value":"Nowoczesna forma, naturalne materiały i perfekcyjnie dopracowane detale sprawiają, że Pod Stokiem Apartamenty zachwycają dziś i pozostaną ponadczasowe przez lata.","editable":true,"label":"Opis standardu"},"standardFile":{"value":null,"editable":true,"label":"Plik standardu wykończenia (PDF, do uzupełnienia)"},"labels":{"value":{"loading":"Ładowanie...","mapAlt":"Rzut domów","area":"Powierzchnia","rooms":"Pokoje","gardenArea":"Ogród/Taras","status":"Status","colUnit":"Lokal","colRooms":"Liczba pokoi","colArea":"Powierzchnia","colGardenArea":"Ogród / Taras","colPricePerM2":"Cena / m²","colPrice":"Cena","colStatus":"Status","colDetails":"Szczegóły","seeMore":"Zobacz","none":"Brak","priceHistory":"Historia cen","download":"Pobierz"},"editable":true,"label":"Etykiety UI"}}},{"id":"localization","component":"Localization","type":"section","label":"Lokalizacja","fields":{"header":{"value":"Lokalizacja","editable":true,"label":"Nagłówek"},"subHeader":{"value":"Wola Justowska to jedna z najbardziej cenionych części Krakowa - łączy bliskość zieleni i spokój z wygodą codziennego życia. W kilka minut można dotrzeć do miejsc idelanych na spacer lub aktywność fizyczną: Parku Decjusza, Lasu Wolskiego, Błoń, Kopca Kościuszki czy tras wzdłuż Rudawy. Jednocześnie